// 对已经通过简历匹配规则检查的候选人简 — 由 Agent 工厂从本体动作 `matchResume`(Agents-generation)生成。
// trigger: MATCH_RULE_CHECK_PASSED → emit: MATCH_PASSED_NEED_INTERVIEW | MATCH_PASSED_NO_INTERVIEW | MATCH_FAILED
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface MatchResumeAgentInput {
  candidate_id: string; // 待匹配的候选人唯一编号 (源: Candidate.candidate_id)
  resume_id: string; // 待匹配的候选人简历唯一编号 (源: Resume.resume_id)
  job_requisition_id: string; // 候选人待匹配的招聘岗位编号 (源: Job_Requisition.job_requisition_id)
  client_id: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段 (源: Client.client_id)
  rule_check_result: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段
  rule_check_reason: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段
}

interface MatchResumeAgentOutput {
  candidate_id: string; // 事件 MATCH_PASSED_NEED_INTERVIEW 的 payload 字段
  job_id: string; // 事件 MATCH_PASSED_NEED_INTERVIEW 的 payload 字段
  matching_score: number; // 事件 MATCH_PASSED_NEED_INTERVIEW 的 payload 字段
  matched_reason_highlights: unknown[]; // 事件 MATCH_PASSED_NEED_INTERVIEW 的 payload 字段
  interview_priority: unknown; // 事件 MATCH_PASSED_NEED_INTERVIEW 的 payload 字段
  match_results: unknown; // 候选人与岗位的匹配结果列表，包含匹配状态、得分、各维度评分明细、推荐建议
  overall_status: string; // 候选人整体匹配状态：匹配或不匹配
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个专业的简历智能匹配评估专家。你的核心职责是对已通过规则校验的候选人简历，与目标招聘岗位进行深度智能匹配评估，给出量化评分和推荐建议，决定候选人是否进入面试或推荐环节。

工作流程：
1. 接收输入：获取 \`candidate_id\`、\`resume_id\` 和 \`job_requisition_id\`（来自 MATCH_RULE_CHECK_PASSED 事件）。
2. 读取数据：获取候选人简历的结构化内容（工作经历、教育背景、技能标签等）和岗位要求（必备技能、加分项、学历要求、工作年限等）。
3. 执行智能匹配：调用 \`matchResumeApi\` 对简历文本和 JD 文本进行综合匹配评分，获取：
   - 整体匹配得分（overall_match_score）
   - 各维度评分明细（技能匹配、学历匹配、经验匹配等）
   - 匹配等级（overall_match_grade）
   - 匹配总结（overall_fit_summary）
4. 判定结果（依据匹配得分和岗位要求）：
   - 匹配通过且需要内部面试（岗位设置了内部面试流程）→ 产出 \`MATCH_PASSED_NEED_INTERVIEW\` 事件。
   - 匹配通过但不需要内部面试（可直接推荐客户）→ 产出 \`MATCH_PASSED_NO_INTERVIEW\` 事件。
   - 匹配未通过（得分低于阈值或硬性条件不满足）→ 产出 \`MATCH_FAILED\` 事件。
5. 更新记录：
   - 写入 \`Candidate_Match_Result\`（overall_match_score、overall_fit_verdict、overall_fit_summary、overall_match_grade）。
   - 更新 \`Application\`（matching_score、status、stage）。

决策依据：
- 匹配通过/不通过的阈值依赖 matchResumeApi 返回的评分结果和岗位的 pass_threshold 配置。
- 是否需要内部面试依赖岗位的 interview_process 字段（是否包含内部面试环节）。
- 硬性条件（如学历、工作年限）不符合时直接判为不匹配，无论技能得分多高。

【前置条件（运行前必须满足；不满足则 fail-close 发拦截/失败事件，不要继续）】
1. MATCH_RULE_CHECK_PASSED事件已送达
2. 候选人(Candidate)记录已创建且candidate_id非空
3. 候选人简历(Resume)已完成结构化解析
4. 至少一个有效的招聘岗位(Job_Requisition)记录存在且hc_status不为"已关闭"`;

export const matchResumeAgent = defineAgent({
  id: "agents-gener-match-resume",
  name: "MatchResumeAgent",
  actor: ["Agent"],
  trigger: ["MATCH_RULE_CHECK_PASSED"],
  emit: ["MATCH_PASSED_NEED_INTERVIEW","MATCH_PASSED_NO_INTERVIEW","MATCH_FAILED"],
  tools: ["matchResumeApi"],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // 调用工具 matchResumeApi
      // const matchResumeApiResult = await ctx.tools.run("matchResumeApi", input);
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      // 决策分支（条件见 SYSTEM_PROMPT / decisionLogic）
      if (decision.pass) {
        await ctx.emit("MATCH_PASSED_NEED_INTERVIEW", { ...input, ...decision });
      } else {
        await ctx.emit("MATCH_FAILED", { ...input, ...decision });
      }
      // 其它分支: MATCH_PASSED_NO_INTERVIEW — 按 SYSTEM_PROMPT 条件补充
      return { ok: true };
  },
});
